CREATE TABLE IF NOT EXISTS categories (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255), slug VARCHAR(255) UNIQUE, sort_order INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS subcategories (id INT AUTO_INCREMENT PRIMARY KEY, category_id INT, name VARCHAR(255), slug VARCHAR(255), sort_order INT DEFAULT 0, FOREIGN KEY (category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS brands (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255), slug VARCHAR(255) UNIQUE, sort_order INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS products (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255), slug VARCHAR(255) UNIQUE, image_url TEXT, category_id INT, subcategory_id INT, brand_id INT, is_active TINYINT(1) DEFAULT 1, sort_order INT DEFAULT 0, FOREIGN KEY (category_id) REFERENCES categories(id), FOREIGN KEY (subcategory_id) REFERENCES subcategories(id), FOREIGN KEY (brand_id) REFERENCES brands(id));
 
